import sys
import json
import numpy as np
import pandas as pd

def to_float(x):
    return float(x)

def round_val(metric, period, value):
    if period in ("WoW", "YoY"):
        return round(to_float(value), 1)
    if metric == "share":
        return round(to_float(value), 1)
    if metric == "revenue":
        return round(to_float(value), 2)
    if metric in ("units", "orders", "rank"):
        return round(to_float(value), 2)
    return round(to_float(value), 2)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    def addfact(entity, metric, period, value, formula):
        if value is None:
            return
        try:
            if pd.isna(value):
                return
        except TypeError:
            pass
        facts.append({
            "entity": str(entity),
            "metric": metric,
            "period": period,
            "value": round_val(metric, period, value),
            "formula": formula
        })

    # --- Totals ---
    total_tw = df["Revenue_TW"].sum(skipna=True)
    total_lw = df["Revenue_LW"].sum(skipna=True)
    ly_series = df["Revenue_LY"]
    total_ly = ly_series.sum(skipna=True) if not ly_series.isna().all() else np.nan

    units_tw = df["Units_TW"].sum(skipna=True)
    units_lw = df["Units_LW"].sum(skipna=True)
    orders_tw = df["Orders_TW"].sum(skipna=True)
    orders_lw = df["Orders_LW"].sum(skipna=True)

    addfact("TOTAL", "revenue", "TW", total_tw, "sum(Revenue_TW)")
    addfact("TOTAL", "revenue", "LW", total_lw, "sum(Revenue_LW)")
    if not pd.isna(total_ly) and total_ly != 0:
        addfact("TOTAL", "revenue", "LY", total_ly, "sum(Revenue_LY)")

    addfact("TOTAL", "units", "TW", units_tw, "sum(Units_TW)")
    addfact("TOTAL", "units", "LW", units_lw, "sum(Units_LW)")
    addfact("TOTAL", "orders", "TW", orders_tw, "sum(Orders_TW)")
    addfact("TOTAL", "orders", "LW", orders_lw, "sum(Orders_LW)")

    if total_lw and not pd.isna(total_lw) and total_lw != 0:
        wow_total = (total_tw - total_lw) / total_lw * 100
        addfact("TOTAL", "revenue", "WoW", wow_total,
                "(sum(Revenue_TW)-sum(Revenue_LW))/sum(Revenue_LW)*100")

    if not pd.isna(total_ly) and total_ly != 0:
        yoy_total = (total_tw - total_ly) / total_ly * 100
        addfact("TOTAL", "revenue", "YoY", yoy_total,
                "(sum(Revenue_TW)-sum(Revenue_LY))/sum(Revenue_LY)*100")

    # --- Top entities by Rank (top 3) ---
    if "Rank" in df.columns:
        top3 = df[df["Rank"] <= 3].sort_values("Rank")
    else:
        top3 = df.sort_values("Revenue_TW", ascending=False).head(3)

    for _, row in top3.iterrows():
        e = row["Entity"]
        addfact(e, "revenue", "TW", row.get("Revenue_TW"), "Revenue_TW")
        if "WoW_Pct" in df.columns:
            addfact(e, "revenue", "WoW", row.get("WoW_Pct"), "WoW_Pct")
        if "YoY_Pct" in df.columns:
            addfact(e, "revenue", "YoY", row.get("YoY_Pct"), "YoY_Pct")
        if "Share_Pct" in df.columns:
            addfact(e, "share", "TW", row.get("Share_Pct"), "Share_Pct")
        if "Rank" in df.columns:
            addfact(e, "rank", "TW", row.get("Rank"), "Rank")

    # --- Biggest / worst WoW mover ---
    if "WoW_Pct" in df.columns and not df["WoW_Pct"].isna().all():
        idx_max = df["WoW_Pct"].idxmax()
        row = df.loc[idx_max]
        addfact(row["Entity"], "revenue", "WoW", row["WoW_Pct"],
                "max(WoW_Pct) across entities")

        idx_min = df["WoW_Pct"].idxmin()
        row = df.loc[idx_min]
        addfact(row["Entity"], "revenue", "WoW", row["WoW_Pct"],
                "min(WoW_Pct) across entities")

    # --- Biggest / worst YoY mover ---
    if "YoY_Pct" in df.columns and not df["YoY_Pct"].isna().all():
        idx_max = df["YoY_Pct"].idxmax()
        row = df.loc[idx_max]
        addfact(row["Entity"], "revenue", "YoY", row["YoY_Pct"],
                "max(YoY_Pct) across entities")

        idx_min = df["YoY_Pct"].idxmin()
        row = df.loc[idx_min]
        addfact(row["Entity"], "revenue", "YoY", row["YoY_Pct"],
                "min(YoY_Pct) across entities")

    # Cap at 25 facts
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
